content.content:
775	        for (int kj = 0; kj < dec::kSeq; ++kj) {
776	            float a = aw[qi * dec::kSeq + kj];
777	            ds[kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale : 0.0f;
778	        }
779	    }
780	    __syncthreads();
781	    // C: dq[qi] = Σ_kj ds[qi,kj]*k[kj]; dk[kj] = Σ_qi ds[qi,kj]*q[qi]. Owner: (sample,pos,head,t).
782	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
783	        const int si = r / (dec::kSeq * dec::kHeads * dec::kDhead);
784	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
785	        const int pos = rem / (dec::kHeads * dec::kDhead);
786	        rem = rem % (dec::kHeads * dec::kDhead);
787	        const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
788	        const int qoff = hh * dec::kDhead;
789	        const int rbase = si * dec::kSeq;
790	        const float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
791	        float dq = 0.0f, dk = 0.0f;
792	        #pragma unroll
793	        for (int kj = 0; kj < dec::kSeq; ++kj) {
794	            dq += ds[pos * dec::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff + t]);
795	            dk += ds[kj * dec::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + qoff + t]);
796	        }
797	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + qoff + t] = dq;             // dq block
798	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + dec::kD + qoff + t] = dk;   // dk block
799	    }
800	    __syncthreads();
801	}
802	
803	// ════════════════════════════════════════════════════════════════════════
804	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
805	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
806	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
807	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
808	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
809	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
810	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
811	//
812	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
813	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
814	//  is the dedicated scratch.dh.
815	// ════════════════════════════════════════════════════════════════════════
816	__device__ void dectc_backward_tile(
817	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
818	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
819	        float* __restrict__ lnvec, float* __restrict__ work2,
820	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
821	    const int nsamp = nrows / dec::kSeq;
822	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
823	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
824	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
825	    for (int li = 0; li < dec::kLayers; ++li) {
826	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
827	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
828	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
829	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
830	    }
831	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
832	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
833	
834	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
835	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
836	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
837	    // First zero scratch.dh for the whole tile (only last positions get grad).
838	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
839	    __syncthreads();
840	    for (int si = 0; si < nsamp; ++si) {
841	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
842	        const int gs = si_global(g0, si);
843	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
844	        int tgt = tgt_ids[gs];
845	        // softmax of cached logits.
846	        float lmax = -CUDART_INF_F;
847	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
848	        lmax = dec_block_max(lmax, red);
849	        float es = 0.0f;
850	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
851	        es = dec_block_sum(es, red);
852	        float inv_es = 1.0f / es;
853	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
854	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
855	            float smo = __expf(lg[o] - lmax) * inv_es;
856	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
857	            lg[o] = dl;
858	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
859	        }
860	        __syncthreads();
861	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
862	        // Then final-norm bwd of that single row → scratch.dh[rlast].
863	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
864	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
865	            float dhn = 0.0f;
866	            for (int o = 0; o < dec::kVocab; ++o)
867	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
868	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
869	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
870	        }
871	        __syncthreads();
872	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
873	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
874	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
875	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
876	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
877	        }
878	        __syncthreads();
879	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
880	        {
881	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
882	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
883	            float sda = 0.0f, sdax = 0.0f;
884	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
885	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
886	            }
887	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
888	            float iv = sc.fni[rlast];
889	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
890	                float dxhat = dyr[j] * w.norm_w[j];
891	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
892	            }
893	            __syncthreads();
894	        }
895	    }
896	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
897	
898	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
899	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
900	    //    recompute). ──
901	    for (int li = dec::kLayers - 1; li >= 0; --li) {
902	        const DecWeights::Layer& L = w.layer[li];
903	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
904	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
905	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
906	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
907	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
908	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
909	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
910	        }
911	        __syncthreads();
912	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
913	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
914	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, L.ff2_w,
915	                                           sc.work, dec::kDff, dec::kD, sA, sB);  // dgact [nrows,dff]
916	        __syncthreads();
917	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
918	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
919	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
920	            sc.work[idx] = dff0;
921	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
922	        }
923	        __syncthreads();
924	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
925	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
926	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, L.ff0_w,
927	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB);  // dx1_ffn [nrows,d]
928	        __syncthreads();
929	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
930	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
931	        __syncthreads();
932	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
933	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
934	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
935	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
936	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
937	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
938	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
939	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
940	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
941	        }
942	        __syncthreads();
943	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
944	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, L.out_w,
945	                                           sc.work, dec::kD, dec::kD, sA, sB);  // dctx
946	        __syncthreads();
947	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
948	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
949	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
950	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
951	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
952	        __syncthreads();
953	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
954	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
955	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, L.in_w,
956	                                           sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB);  // dx_in_attn
957	        __syncthreads();
958	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
959	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
960	        __syncthreads();
961	    }
962	
963	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 acts (bf16); the
964	    //    tok/pos owner-scan (P2) reads dh0 by global token row. ──
965	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
966	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
967	    __syncthreads();
968	}
