1075	// ════════════════════════════════════════════════════════════════════════
1076	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1077	//    tok grad: row r (token id) of tok.weight → owner CTA (r % nCTA); the owner
1078	//    scans ALL T tokens in ascending t, accumulating dh0[t,:] for tokens whose
1079	//    id == r. pos grad: row p → owner; sums dh0[t,:] over t with (t%S)==p.
1080	//    Fixed t-order + single owner per row → deterministic, atomic-free.
1081	//    `tok_ids` is HBM int32 [T]. Writes grad[tok_off..], grad[pos_off..].
1082	// ════════════════════════════════════════════════════════════════════════
1083	__device__ __forceinline__ void dectc_embed_owner_scan(
1084	        const DecActs& acts, const int* __restrict__ tok_ids, int T,
1085	        float* __restrict__ grad, int cta, int nCTA) {
1086	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1087	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1088	    // tok rows owned by this CTA: r in [0,V) with r % nCTA == cta.
1089	    for (int r = cta; r < dec::kVocab; r += nCTA) {
1090	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1091	            float accv = 0.0f;
1092	            for (int t = 0; t < T; ++t)
1093	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1094	            grad[tok_off + (int64_t)r * dec::kD + j] = accv;
1095	        }
1096	    }
1097	    // pos rows owned by this CTA: p in [0,S) with p % nCTA == cta.
1098	    for (int p = cta; p < dec::kSeq; p += nCTA) {
1099	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1100	            float accv = 0.0f;
1101	            for (int t = 0; t < T; ++t)
1102	                if ((t % dec::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1103	            grad[pos_off + (int64_t)p * dec::kD + j] = accv;
1104	        }
1105	    }
1106	}
