770	    }
771	    __syncthreads();
772	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale (FULL, all kj).
773	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
774	    for (int r = threadIdx.x; r < nsamp * vit::kHeads * vit::kSeq; r += blockDim.x) {
775	        const int si = r / (vit::kHeads * vit::kSeq);
776	        int rem = r % (vit::kHeads * vit::kSeq);
777	        const int hh = rem / vit::kSeq, qi = rem % vit::kSeq;
778	        const int qoff = hh * vit::kDhead;
779	        const int rbase = si * vit::kSeq;
780	        const float* aw = attn_w + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;
781	        float datt[vit::kSeq];
782	        #pragma unroll
783	        for (int kj = 0; kj < vit::kSeq; ++kj) {
784	            float acc = 0.0f;
785	            #pragma unroll
786	            for (int t = 0; t < vit::kDhead; ++t)
787	                acc += dctx[(int64_t)(rbase + qi) * vit::kD + qoff + t]
788	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + 2 * vit::kD + qoff + t]);
789	            datt[kj] = acc;
790	        }
791	        float dot = 0.0f;
792	        #pragma unroll
793	        for (int kj = 0; kj < vit::kSeq; ++kj) dot += datt[kj] * aw[qi * vit::kSeq + kj];
794	        float* ds = dsc + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq + qi) * vit::kSeq;
795	        #pragma unroll
796	        for (int kj = 0; kj < vit::kSeq; ++kj) {
797	            float a = aw[qi * vit::kSeq + kj];
798	            ds[kj] = a * (datt[kj] - dot) * scale;
799	        }
