801	    __syncthreads();
802	    // C: dq[qi]=Σ_kj ds[qi,kj]*k[kj]; dk[kj]=Σ_qi ds[qi,kj]*q[qi]. FULL. Owner: (sample,pos,head,t).
803	    for (int r = threadIdx.x; r < nsamp * vit::kSeq * vit::kHeads * vit::kDhead; r += blockDim.x) {
804	        const int si = r / (vit::kSeq * vit::kHeads * vit::kDhead);
805	        int rem = r % (vit::kSeq * vit::kHeads * vit::kDhead);
806	        const int pos = rem / (vit::kHeads * vit::kDhead);
807	        rem = rem % (vit::kHeads * vit::kDhead);
