815	            dq += ds[pos * vit::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + vit::kD + qoff + t]);
816	            dk += ds[kj * vit::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + qoff + t]);
817	        }
818	        dqkv_out[(int64_t)(rbase + pos) * 3 * vit::kD + qoff + t] = dq;             // dq block
819	        dqkv_out[(int64_t)(rbase + pos) * 3 * vit::kD + vit::kD + qoff + t] = dk;   // dk block
