824	// ════════════════════════════════════════════════════════════════════════
825	//  BACKWARD over one TOKEN TILE. Assumes vittc_forward_tile ran for THIS tile.
826	//  Fork B: computes dX via wgmma and WRITES the dY output-adjoints to VitActs
827	//  (dY_qkv/dY_a/dY_ff0/dY_ff2/dY_logits) + dh0 for P2's dW — it does NOT touch
828	//  the weight dW here. ACCUMULATES the 10 LN-vector grads into `lnvec`
829	//  [kNumLnVec × d] (deterministic single-owner-per-j). `B` is the full batch
830	//  (CE mean scale). DELTA 3: head/final-norm bwd on the CLS row (pos 0).
831	// ════════════════════════════════════════════════════════════════════════
832	__device__ void vittc_backward_tile(
833	        const VitWeights& w, int g0, int nrows, int B, const VitActs& acts,
834	        const VitTileScratch& sc, const int* __restrict__ tgt_ids,
835	        float* __restrict__ lnvec, float* __restrict__ work2,
836	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
837	    const int nsamp = nrows / vit::kSeq;
838	    float* gn_n1w[vit::kLayers]; float* gn_n1b[vit::kLayers];
839	    float* gn_n2w[vit::kLayers]; float* gn_n2b[vit::kLayers];
840	    for (int li = 0; li < vit::kLayers; ++li) {
841	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * vit::kD;
842	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * vit::kD;
843	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * vit::kD;
844	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * vit::kD;
845	    }
846	    float* gn_normw = lnvec + (int64_t)8 * vit::kD;
847	    float* gn_normb = lnvec + (int64_t)9 * vit::kD;
848	
849	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B → dY_logits (bf16);
850	    //    head dX → dhn; final-norm bwd → dh on the CLS row (pos 0), zero others. ──
851	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
852	    __syncthreads();
853	    for (int si = 0; si < nsamp; ++si) {
854	        const int rcls = si * vit::kSeq;          // CLS row (pos 0)
855	        const int gs = si_global(g0, si);
856	        float* lg = sc.logits + (int64_t)si * vit::kVocab;
857	        int tgt = tgt_ids[gs];
858	        float lmax = -CUDART_INF_F;
859	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
860	        lmax = vit_block_max(lmax, red);
861	        float es = 0.0f;
862	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
863	        es = vit_block_sum(es, red);
864	        float inv_es = 1.0f / es;
865	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
866	            float smo = __expf(lg[o] - lmax) * inv_es;
867	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
868	            lg[o] = dl;
869	            acts.dY_logits[(int64_t)gs * vit::kVocab + o] = __float2bfloat16(dl);
870	        }
871	        __syncthreads();
872	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j] → stash into work row rcls.
873	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
874	            float dhn = 0.0f;
875	            for (int o = 0; o < vit::kVocab; ++o)
876	                dhn += lg[o] * w.out_w[(int64_t)o * vit::kD + j];
877	            sc.work[(int64_t)rcls * vit::kD + j] = dhn;
878	        }
879	        __syncthreads();
880	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only CLS row.)
881	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
882	            float dhn = sc.work[(int64_t)rcls * vit::kD + j];
883	            float xh = sc.fnx[(int64_t)rcls * vit::kD + j];
884	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
885	        }
886	        __syncthreads();
887	        // LN dx (single CLS row): dxhat=dhn*norm_w; reduce; dh[rcls] = inv*(...).
888	        {
889	            const float* dyr = sc.work + (int64_t)rcls * vit::kD;
890	            const float* xhr = sc.fnx + (int64_t)rcls * vit::kD;
891	            float sda = 0.0f, sdax = 0.0f;
892	            for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
893	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
894	            }
895	            sda = vit_block_sum(sda, red); sdax = vit_block_sum(sdax, red);
896	            float iv = sc.fni[rcls];
897	            for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
898	                float dxhat = dyr[j] * w.norm_w[j];
899	                sc.dh[(int64_t)rcls * vit::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
900	            }
901	            __syncthreads();
902	        }
903	    }
904	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only CLS positions nonzero).
905	
906	    for (int li = vit::kLayers - 1; li >= 0; --li) {
907	        const VitWeights::Layer& L = w.layer[li];
908	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
909	        vittc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
910	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 (bf16).
911	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
912	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
913	            acts.dY_ff2[li][(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
914	        }
915	        __syncthreads();
916	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → sc.work (dr2 no longer needed).
917	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * vit::kD, L.ff2_w,
918	                                           sc.work, vit::kDff, vit::kD, sA, sB);  // dgact [nrows,dff]
919	        __syncthreads();
920	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 (bf16) AND keep fp32 in sc.work for dX.
921	        for (int idx = threadIdx.x; idx < nrows * vit::kDff; idx += blockDim.x) {
922	            float dff0 = sc.work[idx] * vit_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
923	            sc.work[idx] = dff0;
924	            acts.dY_ff0[li][(int64_t)g0 * vit::kDff + idx] = __float2bfloat16(dff0);
925	        }
926	        __syncthreads();
927	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32 → sc.x1.
928	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * vit::kDff, L.ff0_w,
929	                                           sc.x1, /*Kin=*/vit::kD, /*Nout=*/vit::kDff, sA, sB);  // dx1_ffn [nrows,d]
930	        __syncthreads();
931	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
932	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
933	        __syncthreads();
934	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β.
935	        vittc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
936	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
937	        // SAVE residual dr1 into sc.dh (free); da → dY_a (bf16).
938	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
939	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1 (saved across attn bwd)
940	            acts.dY_a[li][(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
941	        }
942	        __syncthreads();
943	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
944	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * vit::kD, L.out_w,
945	                                           sc.work, vit::kD, vit::kD, sA, sB);  // dctx
946	        __syncthreads();
947	        // attention bwd (FULL): (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d]
948	        //   fp32 into work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv (bf16).
949	        vittc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
950	        for (int idx = threadIdx.x; idx < nrows * 3 * vit::kD; idx += blockDim.x)
951	            acts.dY_qkv[li][(int64_t)g0 * 3 * vit::kD + idx] = __float2bfloat16(work2[idx]);
952	        __syncthreads();
953	        // in_proj dX: dx_in_attn = dqkv @ in_w (output width Kin=d, contract Nout=3d).
954	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
955	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * vit::kD, L.in_w,
956	                                           sc.work, /*Kin=*/vit::kD, /*Nout=*/3 * vit::kD, sA, sB);  // dx_in_attn
957	        __syncthreads();
958	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
959	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
960	        __syncthreads();
961	    }
962	
963	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 (bf16); the
964	    //    cls/patch/pos owners (P2) read dh0 by global token row. ──
965	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
966	        acts.dh0[(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.dh[idx]);
967	    __syncthreads();
968	}
