970	// ════════════════════════════════════════════════════════════════════════
971	//  P2 — OUTPUT-STATIONARY dW. Each of the 10 weight matrices (patch_proj +
972	//  in/out/ff0/ff2 ×L + head) dW = dYᵀ @ X is split into 64×N output tiles;
973	//  tile_id % nCTA owns each. The owner CTA contracts the FULL token dim itself
974	//  (ascending-t, no float atomics, no partials) via the validated dW
975	//  orientation. Writes the tile into `grad`.
976	//
977	//  patch_proj dW = dh0_patch^T @ X_patch (K = Tp = nsamp·16; the patch rows of
978	//  dh0, gathered against the patch token rows). The 9 transformer dW use K=T (B
979	//  for the head). To unify, each spec carries an `X_is_patch` flag: when set,
980	//  the dW contracts over the Tp PATCH rows, reading the dY adjoint from dh0's
981	//  patch rows (via a global→patch-row map) and X from X_patch.
982	// ════════════════════════════════════════════════════════════════════════
983	struct VitDwSpec {
984	    const __nv_bfloat16* dY;   // [K, Nout]  (for patch_proj: nullptr — uses dh0)
985	    const __nv_bfloat16* X;    // [K, Kin]
986	    int Nout; int Kin; int K;  // Kin = REAL in-dim; K = contraction length
987	    int Kpad;                  // Kin padded to a multiple of 16 (=64 for patch_proj's Kin=49)... see note
988	    int grad_off;              // element offset of this weight in `grad`
989	    int bias_off;              // element offset of the bias in `grad`
990	    int kind;                  // 0=transformer (dY/X both token rows), 1=patch_proj
991	};
992	
993	// Build the 10 specs (called by all CTAs; cheap). T = B*kSeq; Tp = B*kNPatch.
994	__device__ __forceinline__ void vittc_build_dw_specs(
995	        const VitActs& acts, int B, int T, int Tp, VitDwSpec spec[10]) {
996	    // vit_layout weight tensor indices (and bias idx). Per-layer block base = 4 + li*12:
997	    //   in_w = base+0 (in_b base+1), out_w base+2 (out_b base+3),
998	    //   ff0_w base+8 (ff0_b base+9), ff2_w base+10 (ff2_b base+11).
999	    //   patch_proj.weight=1 (bias=2); head out.weight=30 (out.bias=31).
1000	    // spec[0] = patch_proj; spec[1..8] = transformer (li,kind); spec[9] = head.
1001	    {
1002	        VitDwSpec& sp = spec[0];
1003	        sp.dY = nullptr; sp.X = acts.X_patch; sp.Nout = vit::kD; sp.Kin = vit::kPatch;
1004	        sp.K = Tp; sp.Kpad = vit::kPatch;  // K (contraction over patch rows) IS Tp; Kin padding handled in run_tile
1005	        sp.grad_off = kVitOffsets[1]; sp.bias_off = kVitOffsets[2]; sp.kind = 1;
1006	    }
1007	    for (int s = 0; s < 8; ++s) {
1008	        const int li = s / 4, kk = s % 4;
1009	        const int base = 4 + li * 12;
1010	        VitDwSpec& sp = spec[1 + s];
1011	        sp.K = T; sp.kind = 0; sp.Kpad = 0;
