1126	__device__ __forceinline__ void vittc_clspos_owner_scan(
1127	        const VitActs& acts, int T, float* __restrict__ grad, int cta, int nCTA) {
1128	    const int cls_off = kVitOffsets[0];   // cls_token [1,1,d] → [d]
1129	    const int pos_off = kVitOffsets[3];   // pos.weight [kSeq, d]
1130	    const int nsamp = T / vit::kSeq;
