1137	            grad[cls_off + j] = accv;
1138	        }
1139	    }
1140	    // pos rows: round-robin by position p across CTAs (p in [0,kSeq)).
1141	    for (int p = cta; p < vit::kSeq; p += nCTA) {
1142	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1143	            float accv = 0.0f;
