1145	                if ((t % vit::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * vit::kD + j]);
1146	            grad[pos_off + (int64_t)p * vit::kD + j] = accv;
1147	        }
1148	    }
