1155	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1156	// ════════════════════════════════════════════════════════════════════════
1157	__device__ __forceinline__ void vittc_lnvec_reduce(
1158	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1159	        int nCTA, int cta) {
1160	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1161	        const int goff = kLnVecTensorIdx[v];
1162	        const int64_t gbase = kVitOffsets[goff];
1163	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1164	            float accv = 0.0f;
1165	            for (int c = 0; c < nCTA; ++c)
1166	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * vit::kD + j];
1167	            grad[gbase + j] = accv;
1168	        }
1169	    }
